// Source fixtures: circuitpython-source/src/apps/Orion/modules/wander.py with core/note_array.py,
// core/utils.py, core/music.py and adafruit_ticks (2**29 ms wrap). Traces live in
// fixtures/t09j_source_traces.inc, generated by fixtures/t09j/gen_traces.py under python -I.
// Invariant tests below check monophony, release correspondence, scale membership, gate timing,
// reset and bounds against models that do not reuse the implementation.
#include "domain/modules/registry.hpp"
#include "domain/modules/wander.hpp"
#include "domain/music.hpp"
#include <cassert>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <initializer_list>
#include <limits>

namespace {
using namespace orbit;

struct Pair {
  std::uint8_t pitch;
  std::uint8_t velocity;
};

std::uint32_t g_random_draws = 0;
std::uint32_t next_counter(void* ctx) { return ++*static_cast<std::uint32_t*>(ctx); }

bool equal(const char* a, const char* b) { return std::strcmp(a, b) == 0; }

struct Lcg {
  std::uint32_t s;
  std::uint32_t next() {
    s = s * 1664525U + 1013904223U;
    return s >> 8;
  }
  std::uint32_t range(std::uint32_t n) { return next() % n; }
};

// Replays one module through its descriptor, the same way the chain calls it.
struct Run {
  explicit Run(const ModuleDescriptor& descriptor) : d(descriptor) { d.construct(state); }
  ~Run() { d.destroy(state); }
  Run(const Run&) = delete;
  Run& operator=(const Run&) = delete;

  void set_int(std::uint8_t index, std::int32_t value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::integer(value), global, effects));
  }
  void set_float(std::uint8_t index, float value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::decimal(value), global, effects));
  }
  void set_global(std::uint8_t key, std::uint8_t scale) {
    global.key = key;
    global.scale = scale;
  }
  void stop() { d.reset(state, ResetReason::Stop); }

  NoteBatch batch(std::uint32_t now, std::uint32_t tick, bool running, const NoteBatch& input) {
    NoteBatch output{};
    TransportView view{};
    view.running = running;
    view.tick = tick;
    ProcessContext context{TimeSample{now, 0}, global, view, random};
    d.process(state, context, input, output);
    assert(!output.overflowed());
    assert(output.on.count <= kPolyphony && output.off.count <= kPolyphony);
    return output;
  }

  NoteBatch process(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
                    std::initializer_list<std::uint8_t> off) {
    NoteBatch input{};
    for (const auto& p : on) assert(input.on.append({p.pitch, p.velocity, 0}) == PushResult::Added);
    for (const auto p : off) assert(input.off.append({p, 0, 0}) == PushResult::Added);
    return batch(now, tick, running, input);
  }

  void step(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
            std::initializer_list<std::uint8_t> off, std::initializer_list<Pair> expected_on,
            std::initializer_list<std::uint8_t> expected_off) {
    const auto output = process(now, tick, running, on, off);
    if (!matches(output, expected_on, expected_off)) {
      std::fprintf(stderr, "MISMATCH now=%u tick=%u running=%d out_on=%u out_off=%u\n", now, tick,
                   running ? 1 : 0, static_cast<unsigned>(output.on.count), static_cast<unsigned>(output.off.count));
      for (std::uint16_t i = 0; i < output.on.count; ++i) std::fprintf(stderr, " on %u/%u", output.on.items[i].pitch, output.on.items[i].velocity);
      for (std::uint16_t i = 0; i < output.off.count; ++i) std::fprintf(stderr, " off %u", output.off.items[i].pitch);
      std::fprintf(stderr, "\n");
    }
    assert(matches(output, expected_on, expected_off));
  }

  // A documented deviation (W2): the C++ result must match cpp_*, and the source result must not.
  void step_dev(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
                std::initializer_list<std::uint8_t> off, std::initializer_list<Pair> source_on,
                std::initializer_list<std::uint8_t> source_off, std::initializer_list<Pair> cpp_on,
                std::initializer_list<std::uint8_t> cpp_off) {
    const auto output = process(now, tick, running, on, off);
    assert(matches(output, cpp_on, cpp_off));
    assert(!matches(output, source_on, source_off));
  }

  static bool matches(const NoteBatch& output, std::initializer_list<Pair> on, std::initializer_list<std::uint8_t> off) {
    if (static_cast<std::size_t>(output.on.count) != on.size()) return false;
    if (static_cast<std::size_t>(output.off.count) != off.size()) return false;
    std::size_t i = 0;
    for (const auto& p : on) {
      if (output.on.items[i].pitch != p.pitch || output.on.items[i].velocity != p.velocity) return false;
      ++i;
    }
    i = 0;
    for (const auto p : off) {
      if (output.off.items[i++].pitch != p) return false;
    }
    return true;
  }

  const ModuleDescriptor& d;
  ModuleState state{};
  GlobalState global{};
  RandomSource random{&g_random_draws, next_counter};
};

using TraceFn = void (*)(Run&);
struct NamedTrace {
  const char* name;
  TraceFn run;
};

#include "fixtures/t09j_source_traces.inc"

const WanderModuleState& wander_state(const Run& r) { return r.state.storage.wander; }

bool count_attribute(void* ctx, AttributeDescriptor&) {
  ++*static_cast<std::uint8_t*>(ctx);
  return true;
}

// Source parameters in create_main_parms() order (name, label, default, minimum, maximum).
struct Expect {
  const char* name;
  const char* label;
  std::int32_t value;
  std::int32_t low;
  std::int32_t high;
};
const Expect kExpected[] = {
    {"rate", "RATE", 8, 0, 12},           {"gravity", "GRAV", 50, 0, 100},
    {"min_step", "MIN", 1, 0, 16},        {"max_step", "MAX", 2, 0, 16},
    {"max_deviation", "DEV", 8, 0, 24},   {"tension", "TENS", 0, 0, 100},
    {"rand_seed", "SEED", 0, 0, 10000},   {"loop_length", "LOOP", 0, 0, 128},
    {"retrigger_mode", "RTRG", 0, 0, 2},  {"rhythm", "RTHM", 0, 0, 24},
};

void test_descriptors() {
  const auto* wander = find_module("wander");
  assert(wander && wander == &wander_module_descriptor() && module_at(17) == wander);
  assert(module_count() == 18 && !find_module("phraser"));

  const auto& d = *wander;
  assert(d.version == 1 && d.param_count == 11);
  for (std::size_t i = 0; i < sizeof(kExpected) / sizeof(kExpected[0]); ++i) {
    const auto& spec = d.params[i];
    const auto& e = kExpected[i];
    assert(equal(spec.name, e.name) && equal(spec.display_label, e.label));
    const auto expected_type = std::strcmp(e.name, "retrigger_mode") == 0 ? ParamType::Enumeration : ParamType::Integer;
    assert(spec.type == expected_type && spec.default_value.value.integer == e.value);
    assert(spec.minimum.value.integer == e.low && spec.maximum.value.integer == e.high);
    assert(spec.step.value.integer == 1 && spec.flags == ParamPersist);
  }
  assert(equal(d.params[8].options[0], "STBL") && equal(d.params[8].options[1], "CONT") &&
         equal(d.params[8].options[2], "RTRG") && d.params[8].option_count == 3);

  // GATE: the source has no minmax; the C++ bound is documented as deviation W3.
  const auto& gate = d.params[10];
  assert(equal(gate.name, "gate") && equal(gate.display_label, "GATE") && gate.type == ParamType::Decimal);
  assert(gate.default_value.value.decimal == 100.0f && gate.step.value.decimal == 5.0f);
  assert(gate.minimum.value.decimal == -100000.0f && gate.maximum.value.decimal == 100000.0f);

  // wander.py has no save_attrs: the attribute visitor sees nothing.
  Run r(d);
  std::uint8_t count = 0;
  AttributeVisitor visitor{&count, count_attribute};
  d.attributes(r.state, visitor);
  assert(count == 0);
}

void test_construct_defaults() {
  Run r(wander_module_descriptor());
  const auto& s = wander_state(r);
  assert(s.rate_index == 8 && s.gravity == 50 && s.min_step == 1 && s.max_step == 2);
  assert(s.max_deviation == 8 && s.tension == 0 && s.random_seed_user == 0 && s.loop_length == 0);
  assert(s.retrigger_mode == 0 && s.pattern == 0 && s.gate == 100.0f);
  assert(s.center_note == 60 && s.current_note == 60 && s.last_velocity == 127 && s.last_grid_bin == -1);
  assert(!s.has_active && !s.was_running && s.held.count == 0);
}

// Parameter edits clamp where the source's minmax clamps and reject where the source would index
// past a table. Edits never release notes (EffectNone).
void test_set_param_rules() {
  Run r(wander_module_descriptor());
  std::uint8_t effects = 0xff;
  auto set = [&](std::uint8_t index, ParamValue value) {
    return r.d.set_param(r.state, index, value, r.global, effects) && effects == EffectNone;
  };
  assert(set(1, ParamValue::integer(150)) && wander_state(r).gravity == 100);
  assert(set(2, ParamValue::integer(-3)) && wander_state(r).min_step == 0);
  assert(set(3, ParamValue::integer(40)) && wander_state(r).max_step == 16);
  assert(set(4, ParamValue::integer(30)) && wander_state(r).max_deviation == 24);
  assert(set(5, ParamValue::integer(250)) && wander_state(r).tension == 100);
  assert(set(6, ParamValue::integer(20000)) && wander_state(r).random_seed_user == 10000);
  assert(set(7, ParamValue::integer(200)) && wander_state(r).loop_length == 128);
  assert(set(8, ParamValue::integer(1)) && wander_state(r).retrigger_mode == 1);
  assert(set(9, ParamValue::integer(24)) && wander_state(r).pattern == 24);

  assert(set(10, ParamValue::decimal(37.5f)) && wander_state(r).gate == 37.5f);
  assert(set(10, ParamValue::decimal(250000.0f)) && wander_state(r).gate == 100000.0f);
  assert(set(10, ParamValue::decimal(-250000.0f)) && wander_state(r).gate == -100000.0f);
  assert(set(10, ParamValue::decimal(std::numeric_limits<float>::infinity())) && wander_state(r).gate == 100000.0f);
  assert(!set(10, ParamValue::decimal(std::nanf(""))) && wander_state(r).gate == 100000.0f);
  assert(!set(10, ParamValue::integer(5)));

  assert(!set(0, ParamValue::integer(13)) && wander_state(r).rate_index == 8);
  assert(!set(0, ParamValue::decimal(3.0f)));
  assert(!set(8, ParamValue::integer(3)) && wander_state(r).retrigger_mode == 1);
  assert(!set(9, ParamValue::integer(25)) && wander_state(r).pattern == 24);
  assert(!set(9, ParamValue::integer(-1)));
  assert(!set(11, ParamValue::integer(0)));
  assert(set(0, ParamValue::integer(12)) && wander_state(r).rate_index == 12);
}

// Source traces: every trace replays the source's results through the C++ descriptor.
void test_source_traces() {
  for (std::size_t i = 0; i < sizeof(kWanderTraces) / sizeof(kWanderTraces[0]); ++i) {
    Run r(wander_module_descriptor());
    kWanderTraces[i].run(r);
  }
}

// Gate deadline: a release is due on the first pass strictly after start + int(gate), including
// across the uint32 millisecond wrap. Gate 0 releases on the next millisecond, not the same one.
void test_gate_deadline_strict() {
  for (std::uint32_t gate : {0U, 30U}) {
    for (std::uint32_t start : {0U, 0xFFFFFFF0U}) {
      Run r(wander_module_descriptor());
      r.set_int(0, 0);  // RATE 1/1: 96 ticks, so the walk emits once here.
      r.set_float(10, static_cast<float>(gate));
      const auto first = r.process(start, 0, true, {{60, 100}}, {});
      assert(first.on.count == 1 && first.off.count == 0);
      const auto pitch = first.on.items[0].pitch;
      assert(r.process(start, 0, true, {}, {}).off.count == 0);  // Same millisecond: not yet due.
      std::uint32_t released_at = 0;
      for (std::uint32_t k = 1; k <= 10 && released_at == 0; ++k) {
        const auto out = r.process(start + 10 * k, 0, true, {}, {});
        if (out.off.count == 1) {
          assert(out.off.items[0].pitch == pitch);
          released_at = k;
        }
      }
      assert(released_at == (gate == 0U ? 1U : 4U));
      assert(!wander_state(r).has_active);
    }
  }
}

// Held notes: a 13th hold is not recorded and is counted; the center is the newest held note
// that is still held.
void test_held_notes_and_center() {
  Run r(wander_module_descriptor());
  for (std::uint8_t k = 0; k < 13; ++k) r.process(k, k, false, {{static_cast<std::uint8_t>(40 + k), 100}}, {});
  assert(wander_state(r).held.count == 12 && wander_state(r).held_overflow == 1);
  assert(wander_state(r).center_note == 51);

  Run s(wander_module_descriptor());
  s.process(0, 0, false, {{60, 100}}, {});
  s.process(1, 1, false, {{64, 100}}, {});
  assert(wander_state(s).center_note == 64 && wander_state(s).held.count == 2);
  s.process(2, 2, false, {}, {64});
  assert(wander_state(s).center_note == 60 && wander_state(s).held.count == 1);
  // Re-pressing a held pitch moves it to the newest position and makes it the center.
  s.process(3, 3, false, {{64, 90}}, {});
  s.process(4, 4, false, {{60, 80}}, {});
  assert(wander_state(s).center_note == 60 && wander_state(s).held.items[1].pitch == 60);
  assert(wander_state(s).last_velocity == 80);
}

// Stop clears holds and the walk position but keeps the center; the sounding note is dropped
// without a release (the controller calls all_notes_off). Panic behaves as Stop.
void test_stop_and_reset_reasons() {
  Run r(wander_module_descriptor());
  r.set_float(10, 500.0f);
  const auto first = r.process(0, 0, true, {{62, 111}}, {});
  assert(first.on.count == 1 && wander_state(r).has_active);
  r.process(1, 0, true, {{67, 90}}, {});
  r.stop();
  assert(wander_state(r).held.count == 0 && !wander_state(r).has_active && !wander_state(r).was_running);
  assert(wander_state(r).current_note == wander_state(r).center_note && wander_state(r).last_grid_bin == -1);
  assert(wander_state(r).center_note == 67 && wander_state(r).last_velocity == 90);
  // Later passes with nothing held emit nothing, and no release is left for the dropped note.
  assert(r.process(600, 5, true, {}, {}).off.count == 0);
  assert(r.process(700, 6, true, {}, {62}).off.count == 0);

  r.d.reset(r.state, ResetReason::ParameterChange);  // No-op: parameters edits never reset the walk.
  assert(wander_state(r).center_note == 67);
  r.d.reset(r.state, ResetReason::Init);
  assert(wander_state(r).center_note == 60 && wander_state(r).last_velocity == 127);
}

// A walk with TENS=0 only transposes by scale degrees, so every note after the first step is a
// scale note of the current key (the center is in the key).
void test_walk_stays_on_scale() {
  for (std::uint32_t seed = 1; seed <= 40; ++seed) {
    Lcg rng{seed * 2654435U + 7U};
    const auto key = static_cast<std::uint8_t>(rng.range(12));
    const auto scale = static_cast<std::uint8_t>(rng.range(21));
    const auto length = music::kScaleLengths[scale];
    Run r(wander_module_descriptor());
    r.set_global(key, scale);
    r.set_int(1, static_cast<std::int32_t>(rng.range(101)));
    r.set_int(2, static_cast<std::int32_t>(rng.range(17)));
    r.set_int(3, static_cast<std::int32_t>(rng.range(17)));
    r.set_int(4, static_cast<std::int32_t>(1 + rng.range(24)));
    r.set_int(5, 0);
    r.set_int(6, static_cast<std::int32_t>(rng.range(10001)));
    r.set_int(7, static_cast<std::int32_t>(rng.range(129)));
    r.set_int(8, static_cast<std::int32_t>(rng.range(3)));
    r.set_int(9, static_cast<std::int32_t>(rng.range(25)));
    // Start on a scale note of the key.
    const auto center = static_cast<std::uint8_t>(60 + key + music::kScales[scale][rng.range(length)]);
    std::uint32_t now = 0;
    std::uint32_t tick = 0;
    r.process(now, tick, true, {{center, 100}}, {});
    for (int pass = 0; pass < 800; ++pass) {
      now += 1 + rng.range(20);
      tick += rng.range(3);
      const auto out = r.process(now, tick, true, {}, {});
      for (std::uint16_t i = 0; i < out.on.count; ++i) {
        const auto relative = (static_cast<int>(out.on.items[i].pitch) - key + 120) % 12;
        bool in_scale = false;
        for (std::uint8_t k = 0; k < length; ++k) in_scale = in_scale || music::kScales[scale][k] == relative;
        assert(in_scale);
      }
    }
  }
}

// Random presses, releases, transport toggles, ticks (forward and backwards), parameter edits and
// stops. The model tracks the single sounding note; a stop is the controller's all_notes_off.
// Invariants: at most one note-on and one release per pass; a release always ends the sounding
// note; a note-on only starts when nothing sounds; nothing sounds after the final drain.
void test_monophony_and_release_model() {
  for (std::uint32_t seed = 1; seed <= 48; ++seed) {
    Lcg rng{seed * 7919U + 17U};
    Run r(wander_module_descriptor());
    r.set_global(static_cast<std::uint8_t>(rng.range(12)), static_cast<std::uint8_t>(rng.range(21)));
    r.set_int(0, static_cast<std::int32_t>(rng.range(13)));
    r.set_int(1, static_cast<std::int32_t>(rng.range(101)));
    r.set_int(4, static_cast<std::int32_t>(rng.range(25)));
    r.set_int(5, static_cast<std::int32_t>(rng.range(101)));
    r.set_int(7, static_cast<std::int32_t>(rng.range(129)));
    r.set_int(8, static_cast<std::int32_t>(rng.range(3)));
    r.set_int(9, static_cast<std::int32_t>(rng.range(25)));
    r.set_float(10, static_cast<float>(rng.range(200)) - 50.0f);

    bool pressed[128]{};
    std::uint32_t pressed_count = 0;  // Holds never exceed the module's twelve-entry capacity.
    bool sounding = false;
    std::uint8_t sounding_pitch = 0;
    std::uint32_t now = 0;
    std::uint32_t tick = 0;
    bool running = true;

    auto check = [&](const NoteBatch& out) {
      assert(!out.overflowed());
      assert(out.off.count <= 1 && out.on.count <= 1);
      if (out.off.count == 1) {
        assert(sounding && out.off.items[0].pitch == sounding_pitch);
        sounding = false;
      }
      if (out.on.count == 1) {
        assert(!sounding);
        sounding = true;
        sounding_pitch = out.on.items[0].pitch;
      }
    };

    for (int pass = 0; pass < 3000; ++pass) {
      now += 1 + rng.range(30);
      if (rng.range(50) == 0) running = !running;
      if (rng.range(80) == 0) {
        tick = rng.range(200);  // Transport restart or jump.
      } else {
        tick += rng.range(4);
      }
      NoteBatch input{};
      bool touched[128]{};
      const auto actions = rng.range(3);
      for (std::uint32_t k = 0; k < actions; ++k) {
        const auto pitch = static_cast<std::uint8_t>(36 + rng.range(49));
        if (touched[pitch]) continue;
        touched[pitch] = true;
        if (pressed[pitch]) {
          assert(input.off.append({pitch, 0, 0}) == PushResult::Added);
          pressed[pitch] = false;
          --pressed_count;
        } else if (pressed_count < kPolyphony) {
          assert(input.on.append({pitch, static_cast<std::uint8_t>(1 + rng.range(127)), 0}) == PushResult::Added);
          pressed[pitch] = true;
          ++pressed_count;
        }
      }
      if (rng.range(150) == 0) {
        r.set_int(1, static_cast<std::int32_t>(rng.range(101)));
        r.set_int(0, static_cast<std::int32_t>(rng.range(13)));
      }
      if (rng.range(120) == 0) {
        r.stop();
        sounding = false;  // Controller all_notes_off on Stop.
      }
      check(r.batch(now, tick, running, input));
    }

    // Release every key still held; with nothing held the next pass releases the sounding note.
    NoteBatch release{};
    for (std::uint8_t pitch = 36; pitch < 85; ++pitch) {
      if (!pressed[pitch]) continue;
      assert(release.off.append({pitch, 0, 0}) == PushResult::Added);
    }
    check(r.batch(now + 1, tick, running, release));
    check(r.batch(now + 2, tick, running, NoteBatch{}));
    assert(!sounding && !wander_state(r).has_active && wander_state(r).held.count == 0);
  }
}

// Reports the union size for the report (the budget check is the shared ModuleState size).
void test_state_sizes() {
  std::fprintf(stderr, "t09j sizes: ModuleState=%zu WanderModuleState=%zu\n", sizeof(ModuleState),
               sizeof(WanderModuleState));
  assert(sizeof(ModuleState) >= sizeof(WanderModuleState));
}

}  // namespace

int main() {
  test_descriptors();
  test_construct_defaults();
  test_set_param_rules();
  test_source_traces();
  test_gate_deadline_strict();
  test_held_notes_and_center();
  test_stop_and_reset_reasons();
  test_walk_stays_on_scale();
  test_monophony_and_release_model();
  test_state_sizes();
  std::puts("t09j_wander: all checks passed");
  return 0;
}
